mapper.select:
SELECT id, name, price, stock, status, category_id
FROM product
WHERE id = #{id}

mapper.update:
UPDATE product
SET name = #{request.name}, price = #{request.price}, category_id = #{request.categoryId}
WHERE id = #{id}

UPDATE product
SET stock = stock - #{quantity}
WHERE id = #{id} AND status = 'ON_SALE' AND stock >= #{quantity}

UPDATE product
SET status = #{status}
WHERE id = #{id}

UPDATE product
SET stock = stock + #{quantity}
WHERE id = #{id}

mapper.select:
SELECT p.id, p.name, p.price, p.stock, p.status, p.category_id, c.name AS category_name
FROM product p LEFT JOIN product_category c ON c.id=p.category_id

ORDER BY p.id ASC LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE p.status = 'ON_SALE'

    AND p.category_id = #{categoryId}


    AND p.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'


    AND p.price >= #{minPrice}


    AND p.price <= #{maxPrice}


    AND p.stock > 0

mapper.select:
SELECT p.category_id AS categoryId, c.name AS categoryName, COUNT(*) AS count FROM product p LEFT JOIN product_category c ON c.id = p.category_id WHERE p.status = 'ON_SALE'
AND p.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
AND p.stock > 0
GROUP BY p.category_id, c.name ORDER BY count DESC, p.category_id ASC
